candidate.formal_statement_latex:
There exist oracle PPT algorithms $\mathsf{BS} = (\mathsf{Setup}, \mathsf{KeyGen}, \mathsf{Sign}_1, \mathsf{U}_1, \mathsf{Sign}_2, \mathsf{U}_2, \mathsf{Ver})$ which form a three-move blind signature scheme in the sense of Definition~\ref{def:bs}, which make black-box use of the group in the sense of Definition~\ref{def:bb}, and which have access to a random oracle $\mathsf{H}$, such that the following holds for \emph{every} pairing-free group generator $\mathsf{GGen}$. Write $\mathsf{BS}[\mathsf{GGen}]$ for the scheme obtained by sampling $(\mathbb{G}, p, G) \leftarrow \mathsf{GGen}(1^\lambda)$ and running the algorithms of $\mathsf{BS}$ on the group description $(\mathbb{G}, p, G)$. Then:
\begin{enumerate}
  \item \emph{(Correctness.)} $\mathsf{BS}[\mathsf{GGen}]$ is correct in the sense of Definition~\ref{def:corr}.
  \item \emph{(Blindness.)} For every PPT adversary $\mathcal{A}$ with access to $\mathsf{H}$, $\mathsf{Adv}^{\mathrm{blind}}_{\mathsf{BS}[\mathsf{GGen}]}(\mathcal{A}, \lambda)$ as in Definition~\ref{def:blind} is negligible in $\lambda$.
  \item \emph{(One-more unforgeability from $\mathsf{DL}$.)} If the discrete logarithm assumption holds relative to $\mathsf{GGen}$, i.e.\ $\mathsf{Adv}^{\mathrm{dl}}_{\mathsf{GGen}}(\mathcal{B}, \lambda)$ is negligible for every PPT $\mathcal{B}$, then $\mathsf{Adv}^{\mathrm{omuf}}_{\mathsf{BS}[\mathsf{GGen}]}(\mathcal{A}, \lambda)$ as in Definition~\ref{def:omuf} is negligible for every PPT adversary $\mathcal{A}$ with access to $\mathsf{H}$. Here $\mathcal{A}$ is an arbitrary (not necessarily group-generic, not necessarily algebraic) PPT algorithm which receives the actual group description $(\mathbb{G}, p, G)$, and there is no a~priori bound on the number of signing sessions $\mathcal{A}$ opens, nor on how many of them it keeps open concurrently, beyond $\mathcal{A}$ running in polynomial time.
\end{enumerate}

candidate.definitions_latex:
\begin{definition}[Three-move blind signature scheme]\label{def:bs}
A \emph{three-move blind signature scheme} is a tuple $\mathsf{BS} = (\mathsf{Setup}, \mathsf{KeyGen}, \mathsf{Sign}_1, \mathsf{U}_1, \mathsf{Sign}_2, \mathsf{U}_2, \mathsf{Ver})$ of PPT algorithms, each taking a group description $(\mathbb{G}, p, G)$ as an implicit input and each with oracle access to $\mathsf{H}$:
\begin{itemize}
  \item $\mathsf{Setup}(1^\lambda) \to \mathsf{pp}$;
  \item $\mathsf{KeyGen}(\mathsf{pp}) \to (\mathsf{sk}, \mathsf{pk})$;
  \item $\mathsf{Sign}_1(\mathsf{pp}, \mathsf{sk}) \to (\mathsf{smsg}_1, \mathsf{st_S})$;
  \item $\mathsf{U}_1(\mathsf{pp}, \mathsf{pk}, \mu, \mathsf{smsg}_1) \to (\mathsf{umsg}, \mathsf{st_U})$;
  \item $\mathsf{Sign}_2(\mathsf{umsg}, \mathsf{st_S}) \to \mathsf{smsg}_2$;
  \item $\mathsf{U}_2(\mathsf{smsg}_2, \mathsf{st_U}) \to \sigma \in \{0,1\}^* \cup \{\bot\}$;
  \item $\mathsf{Ver}(\mathsf{pp}, \mathsf{pk}, \mu, \sigma) \to b \in \{0,1\}$, deterministic.
\end{itemize}
A signing session on a message $\mu$ consists of exactly three transmitted messages: $\mathsf{smsg}_1$ from signer to user, then $\mathsf{umsg}$ from user to signer, then $\mathsf{smsg}_2$ from signer to user. No further communication is permitted.
\end{definition}

\begin{definition}[Correctness]\label{def:corr}
$\mathsf{BS}$ is \emph{correct} if for every $\lambda$, every $\mathsf{pp} \in \mathsf{Setup}(1^\lambda)$, every $(\mathsf{sk}, \mathsf{pk}) \in \mathsf{KeyGen}(\mathsf{pp})$ and every $\mu \in \{0,1\}^*$, an honest execution
\[
  (\mathsf{smsg}_1, \mathsf{st_S}) \leftarrow \mathsf{Sign}_1(\mathsf{pp}, \mathsf{sk}),\quad (\mathsf{umsg}, \mathsf{st_U}) \leftarrow \mathsf{U}_1(\mathsf{pp}, \mathsf{pk}, \mu, \mathsf{smsg}_1),
\]
\[
  \mathsf{smsg}_2 \leftarrow \mathsf{Sign}_2(\mathsf{umsg}, \mathsf{st_S}),\quad \sigma \leftarrow \mathsf{U}_2(\mathsf{smsg}_2, \mathsf{st_U})
\]
satisfies $\mathsf{Ver}(\mathsf{pp}, \mathsf{pk}, \mu, \sigma) = 1$ with probability at least $1 - \nu(\lambda)$ for some negligible $\nu$, the probability being over the coins of the four algorithms and over $\mathsf{H}$.
\end{definition}

\begin{definition}[Blindness]\label{def:blind}
For an adversary $\mathcal{A}$ acting as a malicious signer, consider the game: sample $\mathsf{pp} \leftarrow \mathsf{Setup}(1^\lambda)$ and run $\mathcal{A}(\mathsf{pp})$, which outputs a public key $\mathsf{pk}$, two messages $\mu_0, \mu_1 \in \{0,1\}^*$ and a state. Sample $b \leftarrow_{\$} \{0,1\}$. The game then runs two user instances, one on $\mu_b$ and one on $\mu_{1-b}$, each executing $\mathsf{U}_1$ and then $\mathsf{U}_2$ with $(\mathsf{pp}, \mathsf{pk})$; $\mathcal{A}$ supplies all signer messages to both instances and chooses their interleaving. Let $\sigma_0$ and $\sigma_1$ be the outputs of the instances run on $\mu_0$ and on $\mu_1$ respectively. If $\sigma_0 = \bot$ or $\sigma_1 = \bot$, then $\mathcal{A}$ is given $(\bot, \bot)$; otherwise $\mathcal{A}$ is given $(\sigma_0, \sigma_1)$. Finally $\mathcal{A}$ outputs $b' \in \{0,1\}$. Set
\[
  \mathsf{Adv}^{\mathrm{blind}}_{\mathsf{BS}}(\mathcal{A}, \lambda) := \left| \Pr[b' = b] - \tfrac{1}{2} \right| .
\]
$\mathsf{BS}$ is \emph{blind} if this is negligible for every PPT $\mathcal{A}$.
\end{definition}

\begin{definition}[One-more unforgeability]\label{def:omuf}
For an adversary $\mathcal{A}$ acting as a malicious user, consider the game: sample $\mathsf{pp} \leftarrow \mathsf{Setup}(1^\lambda)$ and $(\mathsf{sk}, \mathsf{pk}) \leftarrow \mathsf{KeyGen}(\mathsf{pp})$, initialise a counter $\mathsf{cnt} \leftarrow 0$, a closed-session counter $\ell \leftarrow 0$ and a set $\mathcal{S} \leftarrow \emptyset$, and run $\mathcal{A}(\mathsf{pp}, \mathsf{pk})$ with two oracles:
\begin{itemize}
  \item $\mathsf{S}_1()$: set $\mathsf{cnt} \leftarrow \mathsf{cnt} + 1$, compute $(\mathsf{smsg}_{1}, \mathsf{st_S}^{(\mathsf{cnt})}) \leftarrow \mathsf{Sign}_1(\mathsf{pp}, \mathsf{sk})$, and return $(\mathsf{cnt}, \mathsf{smsg}_{1})$;
  \item $\mathsf{S}_2(\mathsf{sid}, \mathsf{umsg})$: if $\mathsf{sid} \notin \{1, \dots, \mathsf{cnt}\}$ or $\mathsf{sid} \in \mathcal{S}$, return $\bot$; otherwise set $\mathcal{S} \leftarrow \mathcal{S} \cup \{\mathsf{sid}\}$, set $\ell \leftarrow \ell + 1$, and return $\mathsf{Sign}_2(\mathsf{umsg}, \mathsf{st_S}^{(\mathsf{sid})})$.
\end{itemize}
$\mathcal{A}$ finally outputs pairs $(\mu^{(1)}, \sigma^{(1)}), \dots, (\mu^{(k)}, \sigma^{(k)})$ and wins if $k \geq \ell + 1$, the messages $\mu^{(1)}, \dots, \mu^{(k)}$ are pairwise distinct, and $\mathsf{Ver}(\mathsf{pp}, \mathsf{pk}, \mu^{(i)}, \sigma^{(i)}) = 1$ for all $i \in \{1, \dots, k\}$. Set $\mathsf{Adv}^{\mathrm{omuf}}_{\mathsf{BS}}(\mathcal{A}, \lambda) := \Pr[\mathcal{A} \text{ wins}]$. $\mathsf{BS}$ is \emph{one-more unforgeable} if this is negligible for every PPT $\mathcal{A}$. Note that $\mathcal{A}$ may interleave its $\mathsf{S}_1$ and $\mathsf{S}_2$ queries arbitrarily, so any polynomial number of sessions may be open at once.
\end{definition}

\begin{definition}[Black-box use of the group]\label{def:bb}
$\mathsf{BS}$ \emph{makes black-box use of the group} if there is a single tuple of oracle PPT algorithms such that, for every group description $(\mathbb{G}, p, G)$, the algorithms of $\mathsf{BS}$ on that description are obtained by giving those oracle algorithms the following interface, and nothing else: (i) the order $p$ and an opaque handle for the generator $G$; (ii) an oracle that, given handles for $X, Y \in \mathbb{G}$, returns a handle for $X + Y$, and one that, given a handle for $X$, returns a handle for $-X$; (iii) an oracle that, given handles for $X, Y$, returns $1$ if $X = Y$ and $0$ otherwise; (iv) an oracle returning a handle for a uniformly random element of $\mathbb{G}$. The algorithms never read the bit representation of a group element, and group elements appearing in $\mathsf{pp}$, $\mathsf{pk}$, protocol messages and signatures are transmitted as group elements. Equivalently, $\mathsf{BS}$ is well defined as a scheme in the generic group model of Shoup and Maurer. Adversaries are \emph{not} restricted in this way: in Definitions~\ref{def:blind} and~\ref{def:omuf} the adversary receives the real group description and may exploit the representation of group elements arbitrarily.
\end{definition}
